def count_Substrings(s):
    n = len(s)
    count = 0
    for i in range(n):
        for j in range(i, n):
            length = j - i + 1
            digit_sum = sum(int(s[k]) for k in range(i, j + 1))
            if digit_sum == length:
                count += 1
    return count
```

