def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0]
    left, right = 0, n - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid - 1
    return arr[left]
```

