    if n % 2 == 1:
        return arr[-1]
    left, right = 0, n - 1
    while left < right:
        mid = (left + right) // 2
        if mid % 2 == 1:
            if arr[mid] == arr[mid - 1]:
                right = mid - 1
            else:
                left = mid + 1
        else:
