def find_solution(a, b, n):
    if n % gcd(a, b) != 0:
        return None
    g, x, y = extended_gcd(a, b)
    x0 = x * (n // g)
    y0 = y * (n // g)
    k = (x0 * b - y0 * a) // g
    return (x0 + k * b // g, y0 - k * a // g)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    g, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return g, x, y
```

