def is_majority(arr, n, x):
    if binary_search_first(arr, 0, n-1, x) == -1:
        return False
    return arr[binary_search_first(arr, 0, n-1, x) + n // 2] == x

def binary_search_first(arr, low, high, x):
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] < x:
                return mid
            high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

