def is_majority(arr, n, x):
    # Find first occurrence of x
    left = 0
    right = n - 1
    first = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                first = mid
                break
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first == -1:
        return False

    # Check if it's majority: first + n//2 should be the last occurrence
    return arr[first + n // 2] == x
