def get_total_number_of_sequences(m,n): 
    if n == 0: return 1
    if n == 1: return m
    if m < 2: return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for _ in range(n - 1):
        new_dp = [0] * (m + 1)
        for i in range(1, m + 1):
            for prev in range(1, i // 2 + 1):
                new_dp[i] += dp[prev]
        dp = new_dp
    return sum(dp)
```

