def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if n == 1:
        return m

    # T[i][j] = number of valid sequences of length j ending with value i
    T = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        T[i][1] = 1

    for length in range(2, n + 1):
        for end_val in range(1, m + 1):
            start_min = (end_val + 1) // 2
            for start in range(start_min, end_val + 1):
                T[end_val][length] += T[start][length - 1]

    return sum(T[i][n] for i in range(1, m + 1))
