def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1
    for length in range(2, n + 1):
        for start in range(1, m + 1):
            end = min(m, 2 * start)
            for next_val in range(end, start * 2, -1):
                if next_val > m:
                    break
                dp[next_val][length] += dp[start][length - 1]
    total = 0
    for start in range(1, m + 1):
        total += dp[start][n]
    return total
