def get_total_number_of_sequences(m, n):
    if n == 1:
        return m
    if n == 2:
        return m * (m + 1) // 2

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1
        dp[i][2] = i

    for length in range(3, n + 1):
        for last in range(1, m + 1):
            start = max(1, last // 2 + 1)
            dp[last][length] = sum(dp[p][length - 1] for p in range(start, last + 1))

    return dp[m][n]
