def count_Primes_nums(n):
    if n <= 2:
        return 0
    count = 1
    for num in range(3, n, 2):
        is_prime = True
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count
```

