def count_Primes_nums(n):
    def is_prime(k):
        if k <= 1: return False
        if k == 2: return True
        if k % 2 == 0: return False
        i = 3
        while i * i <= k:
            if k % i == 0: return False
            i += 2
        return True
    return sum(is_prime(i) for i in range(n))
