import math

def sumofFactors(n):
    if n % 2 != 0:
        return 0
    res = 1
    i = 2
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count > 0:
            res *= (i**(count+1) - 1) // (i - 1)
        i += 1 if i == 2 else 2
    if n > 1:
        res *= (n**2 - 1) // (n - 1)
    return res
```

```python
def sumofFactors(n: int) -> int:
    if n % 2 != 0:
        return 0
    total = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            s = 1
            t = 1
            while n % d == 0:
                n //= d
                t *= d
                s += t
            total *= s
        d += 1
    if n > 1:
        total *= (1 + n)
    return total
```

