def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0
    # mpis[i] stores the max product of an increasing subsequence ending at i
    mpis = arr[:]
    for i in range(n):
        current_prod = arr[i]
        for j in range(i + 1, n):
            if arr[j] > arr[j - 1]:
                current_prod *= arr[j]
                if current_prod > mpis[j]:
                    mpis[j] = current_prod
            else:
                break
    return max(mpis)
