import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find u, v such that a*u + b*v = g
    def egcd(x, y):
        if y == 0:
            return (1, 0)
        else:
            u, v = egcd(y, x % y)
            return (v, u - (x // y) * v)

    u0, v0 = egcd(a, b)
    # Scale the solution to get a*u + b*v = n
    factor = n // g
    u = u0 * factor
    v = v0 * factor

    # Return one valid pair (any will do)
    return (u, v)
```

