    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = extended_gcd(y, x % y)
        return g, y1, x1 - (x // y) * y1

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    x = x0 * (n // g)
    y = y0 * (n // g)
    return (x, y)
```

