def is_majority(arr, n, x):
    """
    Returns True if x is the majority element in the sorted array,
    i.e., it appears more than n/2 times.
    """
    if n <= 0:
        return False

    # In a sorted array, if x is the majority, it must occupy the middle position.
    mid_index = n // 2
    if arr[mid_index] != x:
        return False

    # Check how many times x appears starting from the middle.
    # Count from mid_index to the end of the array.
    count = 0
    for i in range(mid_index, n):
        if arr[i] == x:
            count += 1
        else:
            break

    # Check how many times x appears ending at the middle.
    count_left = 0
    for i in range(mid_index - 1, -1, -1):
        if arr[i] == x:
            count_left += 1
        else:
            break

    return count + count_left > n // 2
```

