```python
def next_smallest_palindrome(n: int) -> int:
    """Return the next smallest palindrome strictly greater than n."""
    s = str(n)
    length = len(s)
    # Try to make the smallest palindrome larger than n by incrementing the
    # middle digit(s) and mirroring.
    def make_palindrome_from_prefix(prefix: str) -> int:
        # Mirror the prefix to form a palindrome of the same length
        if length % 2 == 0:
            return int(prefix + prefix[::-1])
        else:
            return int(prefix + prefix[-2::-1])

    # Try all prefixes from the original number's prefix up to the full length
    for i in range(length):
        prefix = s[:i+1]
        p = make_palindrome_from_prefix(prefix)
        if p > n:
            return p
    # If no palindrome of the same length is greater, return the next length
    # (all 9s + 1, which is 1 followed by zeros and then 1)
    return int('1' + '0' * (length - 1) + '1')
```

