def find_solution(a, b, n):
    import math
    g = math.gcd(a, b)
    if n % g:
        return None
    def extended_gcd(A, B):
        if B == 0:
            return 1, 0, A
        x1, y1, d = extended_gcd(B, A % B)
        return y1, x1 - (A // B) * y1, d
    x0, y0, _ = extended_gcd(a, b)
    x = x0 * (n // g)
    y = y0 * (n // g)
    return (x, y)
```

