def find_solution(a, b, n):
    def gcd_extended(a, b):
        if b == 0:
            return a, 1, 0
        g, x1, y1 = gcd_extended(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return g, x, y

    g, x, y = gcd_extended(a, b)
    if n % g != 0:
        return None
    k = n // g
    return (x * k, y * k)
```

