def find_solution(a, b, n):
	if a == 0:
		if b == 0:
			return None if n != 0 else (0, 0)
		return (0, n // b) if n % b == 0 else None
	if b == 0:
		return (n // a, 0) if n % a == 0 else None
	if a == 1:
		return (n, 0)
	if b == 1:
		return (0, n)
	g = a if a < b else b
	if a == g:
		return (n // a, 0) if n % a == 0 else None
	if b == g:
		return (0, n // b) if n % b == 0 else None
	for i in range(n // a + 1):
		if (n - i * a) % b == 0:
			return (i, (n - i * a) // b)
	return None
```

