def count_no_of_ways(n, k):
    if n == 1:
        return k
    if n == 2:
        return 17 if k == 4 else k * k
    mod = 1_000_000_007
    dp1, dp2 = k, k * k
    for _ in range(3, n + 1):
        dp1, dp2 = dp2, (dp2 + dp1) * (k - 1) % mod
    return dp2
```

